import{_ as a,H as i,f as n,i as p}from"./chunks/framework.BH2BK_3i.js";const r=JSON.parse('{"title":"31 | 程序如何与操作系统交互？","description":"","frontmatter":{},"headers":[{"level":2,"title":"什么是系统调用？","slug":"什么是系统调用","link":"#什么是系统调用","children":[]},{"level":2,"title":"系统调用 vs 用户函数","slug":"系统调用-vs-用户函数","link":"#系统调用-vs-用户函数","children":[]},{"level":2,"title":"系统调用的基本实现","slug":"系统调用的基本实现","link":"#系统调用的基本实现","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"深入C语言和程序运行原理/31｜程序如何与操作系统交互？.md","filePath":"深入C语言和程序运行原理/31｜程序如何与操作系统交互？.md","lastUpdated":1795558606000}'),e={name:"深入C语言和程序运行原理/31｜程序如何与操作系统交互？.md"};function t(l,s,h,d,k,c){return i(),n("div",null,[...s[0]||(s[0]=[p(`<h1 id="_31-程序如何与操作系统交互" tabindex="-1">31 | 程序如何与操作系统交互？ <a class="header-anchor" href="#_31-程序如何与操作系统交互" aria-label="Permalink to &quot;31 | 程序如何与操作系统交互？&quot;">​</a></h1><p>你好，我是于航。</p><p>在上一讲中我曾提到，你可以将操作系统内核暴露的“系统调用”也作为 API 的一种具体表现形式，因为调用者可以通过这些接口来使用内核提供的某种能力，但是却无需了解它们的内部实现细节。在之前的课程中，我也多次提到过有关系统调用的内容。那么，系统调用究竟是什么？它与我们编写的应用程序函数有何不同？通常情况下它又是怎样实现的呢？这一讲，我们就来看看这些问题的答案。</p><h2 id="什么是系统调用" tabindex="-1">什么是系统调用？ <a class="header-anchor" href="#什么是系统调用" aria-label="Permalink to &quot;什么是系统调用？&quot;">​</a></h2><p>不知道你还记不记得我在 11 讲 “用于低级 IO 接口的操作系统调用”小节中给出的例子，通过这个例子我们能够发现，操作系统调用实际上是由操作系统内核封装好的一些可供上层应用程序使用的接口。这些接口为应用提供了可以按照一定规则访问计算机底层软件与硬件相关服务（如 IO、进程、摄像头等）的能力。其中，内核作为中间层，隔离了用户代码与硬件体系。</p><p>接下来，我们再通过一个简单的例子，来快速回顾下如何在 x86-64 平台上使用系统调用。在大多数情况下，位于内核之上的各类系统库（如 glibc、musl）会将这些系统调用按照不同类别进行封装，并提供可以直接在 C 代码中使用的函数接口。通过这种方式，我们就可以间接</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>地使用系统调用。当然，在这些函数内部，系统调用的具体执行通常是由汇编指令 syscall</span></span></code></pre></div><p>完成的。</p><p>比如，POSIX 标准中有一个名为 getpid 的函数，该函数用于获取当前进程的唯一标识符（ID）。如果查看 musl 中该函数针对 x86-64 平台的具体实现，你会发现这样一段代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;​unistd.h&gt;</span></span>
<span class="line"><span>#include &quot;syscall.h&quot;</span></span>
<span class="line"><span>pid_t getpid(void) {</span></span>
<span class="line"><span> return __syscall(SYS_getpid);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这段 C 代码作为“封装层（Wrapper）”，向上屏蔽了内部的 sys_getpid 系统调用。函数实现中传入的 SYS_getpid 是一个值为 39 的宏常量，这个值便为 sys_getpid 系统调用对应的唯一ID。紧接着，通过名为 __syscall 的另一个函数，程序可以执行系统调用，并获取由内核返回的相关数据。这里，该函数直接由汇编代码定义，内容如下所示：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.global __syscall</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.type __syscall,@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">__syscall</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> movq</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rdi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, %</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rax</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> movq</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rsi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, %</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rdi</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> movq</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rdx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, %</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rsi</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> movq</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rcx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, %</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rdx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> movq</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">r8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, %</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">r10</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> movq</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">r9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, %</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">r8</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> movq</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 8(%</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">rsp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), %</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">r9</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> syscall</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ret</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">在这段</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> 格式的汇编代码中</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">，</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">第</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 4 </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">行的</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> movq</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> 指令将传入该函数的系统调用</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ID</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> 存放到了</span></span></code></pre></div><p>rax 寄存器中；接下来的第 5~10 行，代码将系统调用需要使用的参数也放到了相应寄存器中（这里，你可以看到 SysV 规范中对于普通函数和系统调用参数的不同处理方式）；最后，代</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>码的第 11 行，通过 syscall 指令，系统调用得以被正确执行。</span></span></code></pre></div><p>可以看到，系统调用的使用十分简单。那么，你有没有思考过这个问题：为什么系统调用需要</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用特殊的 syscall 指令，而非“普通”的 call 指令进行调用呢？想要知道答案，那就要先</span></span></code></pre></div><p>从二者之间不同的代码执行环境开始说起了。</p><h2 id="系统调用-vs-用户函数" tabindex="-1">系统调用 vs 用户函数 <a class="header-anchor" href="#系统调用-vs-用户函数" aria-label="Permalink to &quot;系统调用 vs 用户函数&quot;">​</a></h2><p>系统调用与一般函数（或者说“用户函数”）的最大区别在于，系统调用执行的代码位于操作系统底层的内核环境中，而用户函数代码则位于内核之上的应用环境中。这两种环境有时也被称为内核态与用户态。</p><p>现代计算机通常采用名为“保护环（Protection Rings）”的机制来保护整个系统的数据和功能，使其免受故障和外部恶意行为的伤害。这种方式通过提供多种不同层次的资源访问级别，即“特权级别”，来限制不同代码的执行能力。</p><p>比如，在 Intel x86 架构中，特权级别被分为 4 个层次，即 Ring0~Ring3。其中，Ring0 层拥有最高特权，它具有对整个系统的最大控制能力，内核代码通常运行于此。相对地，Ring3 层只有最低特权，这里是应用程序代码所处的位置。而位于两者之间的 Ring1 和 Ring2 层，则通常被操作系统选择性地作为设备驱动程序的“运行等级”。你可以通过下面这张图（图片来自Wikipedia）来直观地理解特权级别的概念。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5C%E8%AF%AD%E8%A8%80%E5%92%8C%E7%A8%8B%E5%BA%8F%E8%BF%90%E8%A1%8C%E5%8E%9F%E7%90%86/images/31/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5C%E8%AF%AD%E8%A8%80%E5%92%8C%E7%A8%8B%E5%BA%8F%E8%BF%90%E8%A1%8C%E5%8E%9F%E7%90%86/images/31/1.png" alt=""></a></p><p>根据特权级别的不同，CPU 能够被允许执行的机器指令以及可使用的寄存器也有所不同。比</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如位于 Ring3 层的应用程序，可以使用最常见的通用目的寄存器，并通过 mov 指令操作其中</span></span></code></pre></div><p>存放的数据。而位于 Ring0 层的内核代码则可以使用除此之外的 cr0、cr1 等控制寄存器，甚</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>至通过 in 与 out 等机器指令，直接与特定端口进行 IO 操作。但如果应用程序尝试跨级别非</span></span></code></pre></div><p>法访问这些被限制的资源，CPU 将抛出相应异常，阻止相关代码的执行。</p><p>到这里，对于“为什么系统调用需要通过特殊的机器指令来使用”这个问题，你应该已经有了答案。系统调用是由内核提供的重要能力，而这些能力的具体实现代码属于内核代码的一部分。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>因此，为了执行这些代码，我们便需要一种能够在 Ring0 层将它们触发的方法，而 syscall</span></span></code></pre></div><p>指令便能够做到这一点。</p><p>最后，再让我们来进一步看看系统调用通常是如何实现的。</p><h2 id="系统调用的基本实现" tabindex="-1">系统调用的基本实现 <a class="header-anchor" href="#系统调用的基本实现" aria-label="Permalink to &quot;系统调用的基本实现&quot;">​</a></h2><p>事实上，在 x86-64 体系中，我们可以采用多种方式来执行一个系统调用。以 30 讲 中“不遵循 ABI 的程序能否运行？”这一小节里的汇编代码为例，在不对编译命令做任何修改的情况下，你也可以使用下面这段代码来完成同样的工作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>extern sub</span></span>
<span class="line"><span>global _start</span></span>
<span class="line"><span>section .text</span></span>
<span class="line"><span>_start:</span></span>
<span class="line"><span> and   rsp,0xfffffffffffffff0</span></span>
<span class="line"><span> sub   rsp, 3</span></span>
<span class="line"><span> mov   esi, 2</span></span>
<span class="line"><span> mov   edi, 1</span></span>
<span class="line"><span> call  sub</span></span>
<span class="line"><span> # use &quot;int&quot; to invoke a system call.</span></span>
<span class="line"><span> mov   ebx, eax</span></span>
<span class="line"><span> mov   eax, 1</span></span>
<span class="line"><span> int   0x80</span></span>
<span class="line"><span>观察上述代码的最后三行，你会发现我们触发 exit 系统调用的方式发生了变化。int 指令是</span></span></code></pre></div><p>一个用于产生软中断的汇编指令，它在调用时会接收一个中断号作为参数。</p><p>当中断发生时，执行环境会从 Ring3 切换至 Ring0，以准备执行内核代码。在这里，CPU 会</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>首先根据 int 指令的参数，来从名为“中断向量表”的结构中查找下一步需要执行的中断处理程</span></span></code></pre></div><p>序。这里对于中断号 0x80 来说，其对应的中断处理程序便专门用于处理，由用户程序发起的系统调用请求。紧接着，这个处理程序会根据程序通过寄存器 eax 传入的系统调用号，来再次查找待执行的系统调用函数。最后，通过 ebx 等寄存器，系统调用函数可以获得所需参数，并完成内核某段具体代码的执行过程。</p><p>在这个过程中发生了特权级别的转换，因此，为了通过隔离执行环境来保证内核安全，CPU在进入内核态前，通常还会进行栈的切换。比如在 Linux 中，CPU 在用户态与内核态会使用不同的栈，来分别处理发生在不同特权级别下的函数调用等过程。每一个进程都对应于独立的内核栈，这个栈中会首先存放与用户态代码执行环境相关的一系列寄存器（如 esp、eip 等）的值。而当发生在内核态的相关过程（如系统调用）结束后，进程使用的栈还需要从内核栈被再次切换回用户栈，并同时恢复保存的寄存器值。</p><p>你可以通过下图来观察上述系统调用的整个执行过程：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5C%E8%AF%AD%E8%A8%80%E5%92%8C%E7%A8%8B%E5%BA%8F%E8%BF%90%E8%A1%8C%E5%8E%9F%E7%90%86/images/31/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5C%E8%AF%AD%E8%A8%80%E5%92%8C%E7%A8%8B%E5%BA%8F%E8%BF%90%E8%A1%8C%E5%8E%9F%E7%90%86/images/31/2.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>以上便是通过 int 指令来进行系统调用的大致过程。需要注意的是，虽然我们可以在 x86-64</span></span></code></pre></div><p>体系上使用这种方式，但它实际仅适用于 i386 体系。在这里，我只是以这种最经典的使用方式为例，来向你展现系统调用的一种基本实现原理。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>而在目前被广泛使用的 x86-64 体系中，通过 syscall 指令进行系统调用仍然是最高效，也</span></span>
<span class="line"><span>最具兼容性的一种方式。syscall 指令的全称为“快速系统调用（Fast System Call）”，CPU</span></span></code></pre></div><p>在执行该指令时不会产生软中断，因此也无需经历栈切换和查找中断向量表等过程，执行效率会有明显的提升。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这一讲，我主要带你看了三个问题，分别是什么是系统调用，系统调用与用户函数的区别，以及系统调用通常是如何实现的。</p><p>系统调用是由操作系统内核封装好的，一些可供上层应用程序使用的接口，这些接口可以让程序方便、安全地通过使用内核的能力，来间接地与底层软件和硬件进行交互。</p><p>与用户函数不同的是，系统调用需要 CPU 执行位于内核中的代码，而现代计算机采用的“保护环”机制则将整个系统的资源访问能力划分为了多个不同的特权级别。其中，Ring0 层拥有最大执行权限，它也是内核代码的运行所在。而 Ring3 层则仅有最小权限，它是上层应用程序的默认运行层级。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>系统调用的经典实现方式是通过基于 int 指令的软中断进行的。借助软中断，CPU 可以从中</span></span></code></pre></div><p>断向量表中找到专门用于处理系统调用的中断处理程序，而该程序再通过由特定寄存器传入的系统调用号，来执行相应的系统调用函数。在这个过程中，操作系统通常会进行由用户栈到内核栈的转换，以及相关寄存器的存储过程。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>而在 x86-64 体系中，通过 syscall 指令进行的系统调用，由于不需要进行软中断和表查</span></span></code></pre></div><p>询，通常会有着更高的执行效率。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>请查阅相关资料，了解 Linux 下的 vDSO 机制是如何参与“虚拟系统调用”的执行过程的，并在评论区说说你的理解。</p><p>今天的课程到这里就结束了，希望可以帮助到你，也希望你在下方的留言区和我一起讨论。同时，欢迎你把这节课分享给你的朋友或同事，我们一起交流。</p>`,56)])])}const g=a(e,[["render",t]]);export{r as __pageData,g as default};
